mapper.select:
SELECT id, order_id, sku_id, expected_qty, received_physical_qty, received_posted_qty, putaway_physical_qty, putaway_posted_qty, closed_qty, stock_sync_status, version
FROM inbound_line
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND id=#{lineId} FOR UPDATE

mapper.update:
UPDATE inbound_line
SET received_physical_qty=received_physical_qty+#{qty}, stock_sync_status='PENDING', version=version+1, updated_at=#{now}
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND id=#{lineId}

UPDATE inbound_line
SET received_posted_qty=received_posted_qty+#{qty}, stock_sync_status=#{syncStatus}, version=version+1, updated_at=#{now}
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND id=#{lineId}
AND received_posted_qty+#{qty}<=received_physical_qty

UPDATE inbound_line
SET putaway_physical_qty=putaway_physical_qty+#{qty}, stock_sync_status='PENDING', version=version+1, updated_at=#{now}
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND id=#{lineId}

UPDATE inbound_line
SET putaway_posted_qty=putaway_posted_qty+#{qty}, stock_sync_status=#{syncStatus}, version=version+1, updated_at=#{now}
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND id=#{lineId}
AND putaway_posted_qty+#{qty}<=putaway_physical_qty

UPDATE inbound_order
SET status=#{status}, version=version+1, updated_at=#{now}
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND id=#{orderId}

mapper.select:
SELECT id, result_code, accepted_qty, rejected_qty, source_version
FROM quality_inspection
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND inbound_line_id=#{lineId}
ORDER BY source_version DESC
LIMIT 1

mapper.update:
UPDATE inbound_task
SET completed_qty=completed_qty+#{qty}, state=#{state}, version=version+1, updated_at=#{now}
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND id=#{taskId}

mapper.select:
SELECT id, part_id, qty, command_id, state
FROM inbound_receipt_part
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND receipt_session_id=#{sessionId}
AND part_id=#{partId}
AND inbound_line_id=#{lineId} FOR UPDATE

SELECT id, business_effect_key, receipt_session_id, part_id, inbound_line_id, command_id, payload_digest, digest_version, state
FROM device_observation_binding
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND device_id=#{deviceId}
AND session_id=#{deviceSessionId}
AND sequence_no=#{sequenceNo} FOR UPDATE

SELECT id, business_effect_key, receipt_session_id, part_id, inbound_line_id, command_id, payload_digest, digest_version, state
FROM device_observation_binding
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND device_id=#{deviceId}
AND session_id=#{deviceSessionId}
AND sequence_no=#{sequenceNo}

mapper.update:
UPDATE device_observation_binding
SET business_effect_key=#{effectKey}, command_id=#{commandId}, state='BOUND', version=version+1, updated_at=#{now}
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND id=#{id}

mapper.select:
SELECT id, external_source, external_no, owner_id, status, version, created_at, updated_at
FROM inbound_order
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}

    AND (created_at < #{page.time} OR (created_at = #{page.time} AND id < #{page.id}))

ORDER BY created_at DESC, id DESC
LIMIT #{page.fetchLimit}

SELECT id, external_source, external_no, owner_id, status, version, created_at, updated_at
FROM inbound_order
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND id=#{orderId}

SELECT id, external_line_id, sku_id, expected_qty, received_physical_qty, received_posted_qty, putaway_physical_qty, putaway_posted_qty, closed_qty, base_unit, stock_sync_status, version
FROM inbound_line
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND order_id=#{orderId}
ORDER BY id

SELECT id, task_type, document_id, document_line_id, planned_qty, completed_qty, state
FROM inbound_task
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND document_id=#{orderId}
ORDER BY created_at
